DiscoveryResult mergeDiscoveryResults({
  required DiscoveryResult? current,
  required DiscoveryResult next,
  required bool keepCurrentWhenNextEmpty,
}) {
  if (next.servers.isEmpty) {
    if (keepCurrentWhenNextEmpty &&
        current != null &&
        current.servers.isNotEmpty) {
      return current;
    }
    return next;
  }

  final merged = <String, DiscoveredServer>{};
  for (final server in next.servers) {
    merged[server.discoveryKey] = server;
  }
  if (current != null) {
    for (final server in current.servers) {
      merged.putIfAbsent(server.discoveryKey, () => server);
    }
  }

  return DiscoveryResult(
    servers: merged.values.toList(growable: false),
    candidateCount: next.candidateCount,
  );
}

class DiscoveredServer {
  const DiscoveredServer({
    required this.endpoint,
    required this.handshake,
    required this.latencyMs,
  });

  final ServerEndpoint endpoint;
  final ServerHandshake handshake;
  final int latencyMs;

  String get discoveryKey {
    final ref = handshake.serverRef.trim().toLowerCase();
    final name = handshake.serverName.trim().toLowerCase();
    if (ref.isNotEmpty && ref != 'unknown' && ref != 'legacy-healthz') {
      return '$ref|$name';
    }
    return endpoint.label.toLowerCase();
  }
}

String driverUrlForRs(DiscoveredServer server) {
  final ref = server.handshake.serverRef.trim().toLowerCase();
  final name = server.handshake.serverName.trim().toLowerCase();
  if (ref == '5070' || name == 'rp-scale-5070') {
    return 'http://100.117.62.18:39117';
  }
  if (ref == 'rp-scale-godex-2' || name == 'rp-scale-godex-2') {
    return 'http://100.117.62.18:${server.endpoint.port}';
  }
  return server.endpoint.baseUrl;
}

String printTargetLabel(DiscoveredServer server) {
  final ref = server.handshake.serverRef.trim();
  final name = server.handshake.serverName.trim();
  final serverName = ref.isNotEmpty && ref != 'unknown' ? ref : name;
  final label = serverName.isEmpty ? server.endpoint.label : serverName;
  return '$label @ ${server.endpoint.port}';
}

